/**
 * Loader for the B1 pull-request-review oracle vectors.
 *
 * The fixture is generated by
 * `apps/crq-python/pr_review_findings_vector_emit_b1.py` from the real
 * `pr_review_findings` module. It contains no paths, host data or
 * credentials. A long periodic string input is encoded as
 * `{"repeat": {"text": unit, "count": n}}`; {@link expandInput} restores the
 * exact Python string before a case runs.
 */
import { readFileSync } from 'node:fs';
import {
  JsonNumber,
  JsonObject,
  parseJsonValue,
  type JsonValue,
} from '../../../src/policy/crq/jsonValue.js';

const VECTOR_URL = new URL(
  '../../../apps/crq-python/fixtures/crq-pr-review-b1/vectors.json',
  import.meta.url,
);

export interface PrReviewCase {
  readonly family: string;
  readonly name: string;
  readonly source: string;
  readonly input: JsonObject;
  readonly expect: JsonObject;
}

export function loadPrReviewVectors(): readonly PrReviewCase[] {
  const document = parseJsonValue(readFileSync(VECTOR_URL, 'utf8'));
  if (!(document instanceof JsonObject)) throw new Error('pr-review vectors: not an object');
  const families = document.get('families');
  if (!Array.isArray(families)) throw new Error('pr-review vectors: missing families');
  const cases: PrReviewCase[] = [];
  for (const family of families) {
    if (!(family instanceof JsonObject)) throw new Error('pr-review vectors: bad family');
    const name = requireString(family.get('family'), 'family');
    const list = family.get('cases');
    if (!Array.isArray(list)) throw new Error(`pr-review vectors: ${name} has no cases`);
    for (const entry of list) {
      if (!(entry instanceof JsonObject)) throw new Error(`pr-review vectors: bad ${name} case`);
      cases.push({
        family: name,
        name: requireString(entry.get('name'), `${name}.name`),
        source: requireString(entry.get('source'), `${name}.source`),
        input: requireObject(entry.get('input'), `${name}.input`),
        expect: requireObject(entry.get('expect'), `${name}.expect`),
      });
    }
  }
  return cases;
}

/**
 * Restore a repeat-encoded string. The descriptor is unambiguous because it is
 * the only shape this fixture uses and every vector is synthetic.
 */
export function expandInput(value: JsonValue): JsonValue {
  if (value instanceof JsonObject) {
    const repeat = value.get('repeat');
    if (value.entries.length === 1 && repeat instanceof JsonObject) {
      const text = repeat.get('text');
      const count = repeat.get('count');
      if (typeof text === 'string' && count instanceof JsonNumber && count.kind === 'int') {
        return text.repeat(Number(count.integer as bigint));
      }
    }
    return new JsonObject(value.entries.map(([key, item]) => [key, expandInput(item)]));
  }
  if (Array.isArray(value)) return value.map(expandInput);
  return value;
}

export function requireObject(value: JsonValue | undefined, what: string): JsonObject {
  if (!(value instanceof JsonObject)) throw new Error(`${what}: expected an object`);
  return value;
}

export function requireString(value: JsonValue | undefined, what: string): string {
  if (typeof value !== 'string') throw new Error(`${what}: expected a string`);
  return value;
}

export function requireNumber(value: JsonValue | undefined, what: string): number {
  if (typeof value === 'number' && Number.isInteger(value)) return value;
  if (value instanceof JsonNumber && value.kind === 'int') {
    const converted = Number(value.integer);
    if (Number.isSafeInteger(converted)) return converted;
  }
  throw new Error(`${what}: expected an integer`);
}

export function arrayField(object: JsonObject, key: string): readonly JsonValue[] {
  const value = object.get(key);
  if (!Array.isArray(value)) throw new Error(`${key}: expected an array`);
  return value;
}

export function optionalString(value: JsonValue | undefined): string | undefined {
  return typeof value === 'string' ? value : undefined;
}
